static void check_hw_pbc ( struct _adapter * padapter ) { u8 tmp1byte ; r8712_write8 ( padapter , MAC_PINMUX_CTRL , ( GPIOMUX_EN | GPIOSEL_GPIO ) ) ; tmp1byte = r8712_read8 ( padapter , GPIO_IO_SEL ) ; tmp1byte &= ~ ( HAL_8192S_HW_GPIO_WPS_BIT ) ; r8712_write8 ( padapter , GPIO_IO_SEL , tmp1byte ) ; tmp1byte = r8712_read8 ( padapter , GPIO_CTRL ) ; if ( tmp1byte == 0xff ) { return ; } if ( tmp1byte & HAL_8192S_HW_GPIO_WPS_BIT ) { netdev_dbg ( padapter -> pnetdev , "CheckPbcGPIO - PBC is pressed !!!!\n" ) ; kill_pid ( find_vpid ( padapter -> pid ) , SIGUSR1 , 1 ) ; } } 